CREATE DATABASE P;
CREATE TABLE CustomerChurn (
    CustomerID VARCHAR(10) PRIMARY KEY,
    Name VARCHAR(100),
    Age INT,
    Gender VARCHAR(10),
    SubscriptionType VARCHAR(20),
    SubscriptionDate DATE,
    LastLoginDate DATE,
    TotalSessions INT,
    FeedbackScore INT,
    IsChurned BIT
);
SELECT * FROM CustomerChurn;

-- 1.Total number of active vs churned customers (by SubscriptionType).
SELECT
SubscriptionType,
CASE
WHEN IsChurned = 1 THEN 'Churned'
ELSE 'Active'
END AS Status,
COUNT(*) AS TotalCustomers
FROM CustomerChurn
GROUP BY SubscriptionType, IsChurned
ORDER BY SubscriptionType;

-- 2. Average Feedback Score by SubscriptionType and Gender
SELECT
SubscriptionType, Gender,
ROUND(AVG(FeedbackScore),2) AS AvgFeedbackScore
FROM CustomerChurn
GROUP BY SubscriptionType, Gender
ORDER BY SubscriptionType, Gender;

-- 3. Customers who attended less than 5 sessions and gave feedback less than 5
SELECT
CustomerID,
Name,
TotalSessions,
FeedbackScore
FROM CustomerChurn
WHERE TotalSessions < 5
AND FeedbackScore < 5;

-- 4. Customers who have not logged in for the last 60 days
SELECT
CustomerID,
Name,
LastLoginDate
FROM CustomerChurn
WHERE LastLoginDate < DATE_SUB(CURDATE(), INTERVAL 60 DAY);

-- 5. Churn Rate by SubscriptionType
SELECT
SubscriptionType,
COUNT(*) AS TotalCustomers,
SUM(IsChurned) AS ChurnedCustomers,
ROUND(
(SUM(IsChurned) * 100.0) / COUNT(*),
2
) AS ChurnRatePercent
FROM CustomerChurn
GROUP BY SubscriptionType;

-- 6. Top 10 Customers with Longest Subscriptions
SELECT
CustomerID,
Name,
SubscriptionType,
SubscriptionDate,
DATEDIFF(CURDATE(), SubscriptionDate) AS SubscriptionDays
FROM CustomerChurn
ORDER BY SubscriptionDate ASC
LIMIT 10;

-- 7. Age Group Wise Churn Analysis
SELECT
CASE
WHEN Age BETWEEN 18 AND 25 THEN '18-25'
WHEN Age BETWEEN 26 AND 35 THEN '26-35'
WHEN Age BETWEEN 36 AND 45 THEN '36-45'
WHEN Age BETWEEN 46 AND 55 THEN '46-55'
ELSE '56+'
END AS AgeGroup,
COUNT(*) AS TotalCustomers,
SUM(IsChurned) AS ChurnedCustomers,
ROUND(
(SUM(IsChurned) * 100.0) / COUNT(*),
2
) AS ChurnRatePercent

FROM CustomerChurn
GROUP BY AgeGroup
ORDER BY AgeGroup;




